def create_wire_and_verify(lib, cell, points):
    import pyAether as pyScript
    cv = pyScript.dbOpenCV(lib=lib, cell=cell, view="schematic")
    wire_figs = pyScript.dbCrtSchWire(cv=cv, point=points)
    if not wire_figs:
        return False
    return bool(pyScript.dbSchIsWire(wire_figs[0]))

